-- =====================================================================================
-- Wallet handles (rule 9): 18 October 2026
-- Adds a unique, nullable `handle` (shown as @handle, e.g. Dennis Kibet -> @denniskibet) to users and
-- partners. Same change as database/migrations/2026_10_18_000041_add_handle_to_users_table.php and
-- 2026_10_18_000042_add_handle_to_partners_table.php.
-- Works on MariaDB 10.3 (live) and MySQL 8+/9 (local). Safe to run more than once. No data deleted.
--
-- The handles themselves are generated by the app (collisions get 2, 3, ...). After this script run:
--   php artisan handles:backfill --dry-run     (review, including collisions)
--   php artisan handles:backfill
--
-- Back up first:   mysqldump --single-transaction --routines --triggers <database> > backup.sql
-- Run:             mysql <database> < database/sql/2026_10_18_wallet_handles.sql
-- =====================================================================================

SET @sql = (SELECT IF(COUNT(*) = 0,
  'ALTER TABLE `users` ADD COLUMN `handle` VARCHAR(64) NULL DEFAULT NULL AFTER `name`, ADD UNIQUE INDEX `users_handle_unique` (`handle`)',
  'SELECT ''users.handle already exists'' AS note')
  FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'handle');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql = (SELECT IF(COUNT(*) = 0,
  'ALTER TABLE `partners` ADD COLUMN `handle` VARCHAR(64) NULL DEFAULT NULL AFTER `name`, ADD UNIQUE INDEX `partners_handle_unique` (`handle`)',
  'SELECT ''partners.handle already exists'' AS note')
  FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'partners' AND column_name = 'handle');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

INSERT INTO `migrations` (`migration`, `batch`)
SELECT m.migration, m.batch FROM (
  SELECT '2026_10_18_000041_add_handle_to_users_table' AS migration, COALESCE(MAX(batch), 0) + 1 AS batch FROM `migrations`
) m
WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE migration = '2026_10_18_000041_add_handle_to_users_table');

INSERT INTO `migrations` (`migration`, `batch`)
SELECT m.migration, m.batch FROM (
  SELECT '2026_10_18_000042_add_handle_to_partners_table' AS migration, COALESCE(MAX(batch), 0) + 1 AS batch FROM `migrations`
) m
WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE migration = '2026_10_18_000042_add_handle_to_partners_table');

SELECT 'Done: handle columns ready. Now run: php artisan handles:backfill --dry-run, then without --dry-run' AS result;
